\begin{proposition}\label{pro:decomposition}
Suppose that Assumptions \ref{asp:apdx_error} - \ref{asp:apdx_groupandparameterssize} hold. With probability at least $1-O(\min\{N_o^{-9},T_o^{-9}\})$, we have 
\begin{align*}
&\widehat{m}_{o,it_o} - m_{{o,it_o}} \\
&=  X_{o,i}^\top  \left( \sum_{j \in \calI_o } \omega_{j t_o} X_{o,j} X_{o,j}^\top  \right)^{-1}  \sum_{j \in \calI_o } \omega_{j t_o} \epsilon_{jt_o} X_{o,j}  +  Z_{o,t_o}^\top  \left( \sum_{s \in \calT_o } \omega_{is} Z_{o,s} Z_{o,s}^\top  \right)^{-1}  \sum_{s \in \calT_o } \omega_{is} \epsilon_{is} Z_{o,s} + \calR_{o,i}^{M},
\end{align*}
where
\begin{align*}
\max_i||\calR_{o,i}^{M}|| &\leq C_M 
\left(
\frac{\sigma^2}{\psi_{\min,o}} \frac{\kappa_o^5 \mu_o r \max\{N_o \log N_o,T_o \log T_o \}}{\min\{N_o , T_o \}} +
 \sigma \frac{\kappa_o^4 \mu_o^2 r^2 \max \{ \sqrt{N_o \log N_o}, \sqrt{T_o \log T_o} \}}{ \min \{N_o^{\frac{3}{2}}, T_o^{\frac{3}{2}} \}} \right.\\
&\qquad \qquad \left. + \sigma \frac{\vartheta_o \mu_o^2 r^2 \kappa_o^3 \max \{\sqrt{N_o \log N_o}, \sqrt{T_o \log T_o} \}}{ N_o \min \{N_o, T_o \}},
\right)
\end{align*}
$C_M > 0$ is an absolute constant.
\end{proposition}

\subsection{A Gaussian-to-Gaussian Comparison Lemma}\label{sec: Gaussian vs Gaussian}
The proofs of the main results in this section rely on the following lemma. Let $V$ and $Y$ be centered Gaussian random vectors in $\RR^{p}$
with covariance matrices $\Sigma^{V}$ and
$\Sigma^{Y}$, respectively. The following lemma compares the distribution functions
of $\max_{1 \leq j \leq p}V_{j} \text{and} \max_{1 \leq j \leq p} Y_{j}$
in terms of $p$ and
\begin{equation*}
\Delta_0:=\max_{1\leq j,k\leq p}\left|\Sigma^V_{jk}-\Sigma^Y_{jk}\right|.
\end{equation*}


\begin{lemma}[Comparison of Distributions of Gaussian Maxima]\label{lemma: distances Gaussian to Gaussian}
Suppose that there are some constants $0 < c_{1} < C_{1}$ such that  $c_{1} \leq \Sigma^Y_{jj}\leq C_{1}$ for  all $1\leq j \leq p$.
Then there exists a constant $C>0$ depending only on $c_{1}$ and $C_{1}$ such that
\begin{equation*}
\sup_{t\in\RR}\left|\Pr\left(\max_{1 \leq j \leq p} V_{j}\leq t\right)-\Pr\left(\max_{1 \leq j \leq p} Y_{j}\leq t\right)\right| \leq  C\Delta_{0}^{1/3}(1 \vee \log (p/\Delta_0))^{2/3}.
\end{equation*}
\end{lemma}
